"use strict";

const http = require("http");
const https = require("https");

function readStatus(mod, url, agent) {
  return new Promise((resolve, reject) => {
    const req = mod.request(url, { agent, timeout: 1000 }, (res) => {
      res.resume();
      res.on("end", () => resolve({ statusCode: res.statusCode, sameAgent: req.agent === agent }));
    });
    req.on("error", reject);
    req.end();
  });
}

exports.probe = async function probe() {
  const httpAgent = new http.Agent({ keepAlive: true, maxSockets: 2, maxFreeSockets: 1 });
  const httpsAgent = new https.Agent({ keepAlive: true, maxSockets: 3, maxFreeSockets: 1 });
  const httpName = httpAgent.getName({ host: "agent.example.invalid", port: 8080 });
  const httpsName = httpsAgent.getName({ host: "secure.example.invalid", port: 9443 });
  const httpResult = await readStatus(http, "http://example.invalid/agent-http", httpAgent);
  const httpsResult = await readStatus(https, "https://example.invalid/agent-https", httpsAgent);
  httpAgent.destroy();
  httpsAgent.destroy();

  return [
    "httpnpm.agent-options=" + (httpResult.sameAgent && httpsResult.sameAgent),
    httpAgent.maxSockets,
    httpsAgent.maxSockets,
    httpName,
    httpsName,
    httpResult.statusCode,
    httpsResult.statusCode,
  ].join("|");
};
